bool StructTraits<::arc::mojom::PurchaseDetails::DataView, ::arc::mojom::PurchaseDetailsPtr>::Read(
    ::arc::mojom::PurchaseDetails::DataView input,
    ::arc::mojom::PurchaseDetailsPtr* output) {
  bool success = true;
  ::arc::mojom::PurchaseDetailsPtr result(::arc::mojom::PurchaseDetails::New());
  
      if (success && !input.ReadItemId(&result->item_id))
        success = false;
      if (success && !input.ReadPurchaseToken(&result->purchase_token))
        success = false;
      if (success)
        result->acknowledged = input.acknowledged();
      if (success && !input.ReadPurchaseState(&result->purchase_state))
        success = false;
      if (success && !input.ReadPurchaseTime(&result->purchase_time))
        success = false;
      if (success)
        result->will_auto_renew = input.will_auto_renew();
  *output = std::move(result);
  return success;
}

